def form {r c d : ℕ} (a : Fin r → Fin c → ℝ)
    (u : Fin r → Fin d → ℝ) (v : Fin c → Fin d → ℝ) : ℝ :=
  ∑ i, ∑ j, a i j * (∑ l, u i l * v j l)

