def values {r c : ℕ} (a : Fin r → Fin c → ℝ) : Set ℝ :=
  {z | ∃ (d : ℕ) (u : Fin r → Fin d → ℝ) (v : Fin c → Fin d → ℝ),
    (∀ i, ∑ l, (u i l) ^ 2 ≤ 1) ∧ (∀ j, ∑ l, (v j l) ^ 2 ≤ 1) ∧ z = |form a u v|}

