def cubeForm {r c : ℕ} (a : Fin r → Fin c → ℝ) (n : ℕ)
    (f : Fin r → Cube n → ℝ) (g : Fin c → Cube n → ℝ) : ℝ :=
  average n (fun x => ∑ i, ∑ j, a i j * (f i x * g j x))

